import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CRfKVJQk.js";const p=JSON.parse('{"title":"Performance","description":"What Liquid Glass costs at runtime on Android, iOS and the web, how to measure it, and the benchmark method for React Native glass views.","frontmatter":{"description":"What Liquid Glass costs at runtime on Android, iOS and the web, how to measure it, and the benchmark method for React Native glass views.","head":[["link",{"rel":"canonical","href":"https://sachinmeenasipl.github.io/react-native-glass-effect/features/performance"}],["meta",{"property":"og:url","content":"https://sachinmeenasipl.github.io/react-native-glass-effect/features/performance"}],["meta",{"property":"og:title","content":"Performance · Liquid Glass for React Native"}],["meta",{"property":"og:description","content":"What Liquid Glass costs at runtime on Android, iOS and the web, how to measure it, and the benchmark method for React Native glass views."}],["meta",{"name":"twitter:title","content":"Performance · Liquid Glass for React Native"}],["meta",{"name":"twitter:description","content":"What Liquid Glass costs at runtime on Android, iOS and the web, how to measure it, and the benchmark method for React Native glass views."}]]},"headers":[],"relativePath":"features/performance.md","filePath":"features/performance.md"}'),o={name:"features/performance.md"};function i(d,e,n,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><p>What glass costs, where the cost comes from, and how to measure it in your app. To choose a budget per view, see <a href="/react-native-glass-effect/features/quality">Quality</a>.</p><h2 id="where-the-cost-comes-from" tabindex="-1">Where the cost comes from <a class="header-anchor" href="#where-the-cost-comes-from" aria-label="Permalink to &quot;Where the cost comes from&quot;">​</a></h2><h3 id="android-12-shader-and-blur-renderers" tabindex="-1">Android 12+ (<code>shader</code> and <code>blur</code> renderers) <a class="header-anchor" href="#android-12-shader-and-blur-renderers" aria-label="Permalink to &quot;Android 12+ (`shader` and `blur` renderers)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>Cost</th></tr></thead><tbody><tr><td><code>GlassBackdrop</code> recording its children</td><td>Low: it records a GPU display list (a <code>RenderNode</code>), not pixels</td></tr><tr><td>Each glass view, each frame the content under it changes</td><td>One GPU blur pass, plus the refraction shader on Android 13+</td></tr><tr><td>A glass view moving (scrolling, animating)</td><td>It redraws every frame it moves, whatever the quality</td></tr><tr><td>Content changing <strong>far</strong> from every glass view</td><td>Nothing: those changes are skipped (<code>skippedFarChanges</code> in <a href="/react-native-glass-effect/features/diagnostics">Diagnostics</a>)</td></tr><tr><td>Nothing moving or changing</td><td>Nothing: glass doesn&#39;t redraw</td></tr></tbody></table><p>The work grows with the number of glass views, their size on screen and the blur radius.</p><h3 id="android-7–11-compat-renderer" tabindex="-1">Android 7–11 (<code>compat</code> renderer) <a class="header-anchor" href="#android-7–11-compat-renderer" aria-label="Permalink to &quot;Android 7–11 (`compat` renderer)&quot;">​</a></h3><p>The backdrop is captured into a bitmap and blurred on the CPU. Captures are throttled by quality: every frame at <code>high</code>, at most every 32 ms at <code>medium</code>, at most every 100 ms at lower resolution at <code>low</code>, and once at <code>static</code>. A capture that takes more than about 8 ms risks dropping frames.</p><h3 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h3><p>With the default system renderer, UIKit draws the glass, and its cost isn&#39;t visible to the library. Apple advises keeping overlapping blur views few. The Metal shader renderer (<code>iosRenderer=&quot;shader&quot;</code>) also samples the backdrop and runs a shader per glass view, so it costs more than the system glass.</p><h3 id="web" tabindex="-1">Web <a class="header-anchor" href="#web" aria-label="Permalink to &quot;Web&quot;">​</a></h3><p>The browser draws <code>backdrop-filter</code>. Its cost depends on the browser, the GPU and the blurred area. Large blurred areas over animating content cost the most.</p><h2 id="what-quality-auto-does-for-you" tabindex="-1">What <code>quality=&quot;auto&quot;</code> does for you <a class="header-anchor" href="#what-quality-auto-does-for-you" aria-label="Permalink to &quot;What `quality=&quot;auto&quot;` does for you&quot;">​</a></h2><ol><li>A high-end Android 13+ device gets <code>high</code>; others get <code>medium</code>.</li><li>A low-RAM phone, or battery saver on, drops to <code>low</code>, and updates live when battery saver toggles.</li><li>More than 6 glass views on screen drops one step; more than 12 drops to <code>low</code>.</li></ol><h2 id="battery" tabindex="-1">Battery <a class="header-anchor" href="#battery" aria-label="Permalink to &quot;Battery&quot;">​</a></h2><ul><li><code>motionLighting</code> keeps the gyroscope running while the glass is on screen. Use it on one hero element.</li><li>Glass over constantly changing content (video, Lottie, spinners) redraws every frame. Keep animations away from under glass when you can.</li></ul><h2 id="measuring-in-your-app" tabindex="-1">Measuring in your app <a class="header-anchor" href="#measuring-in-your-app" aria-label="Permalink to &quot;Measuring in your app&quot;">​</a></h2><h3 id="library-counters" tabindex="-1">Library counters <a class="header-anchor" href="#library-counters" aria-label="Permalink to &quot;Library counters&quot;">​</a></h3><p><code>getGlassStats()</code> counts the work done since the last <code>resetGlassStats()</code>: draws, GPU blur passes, shader passes, compat captures and their time, skipped far changes, solid draws and live glass views. See <a href="/react-native-glass-effect/features/diagnostics">Diagnostics</a>. On iOS only <code>liveGlassViews</code> is filled.</p><h3 id="frame-timing-android" tabindex="-1">Frame timing (Android) <a class="header-anchor" href="#frame-timing-android" aria-label="Permalink to &quot;Frame timing (Android)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dumpsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gfxinfo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your.packag</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> framestats</span></span></code></pre></div><p>Or Android Studio → Profiler → System trace, and look at RenderThread time while scrolling. Profile on a real mid-range phone: emulators often have no real GPU.</p><h2 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;Benchmarks&quot;">​</a></h2><p>No benchmark results are published yet. The library won&#39;t claim numbers it hasn&#39;t measured. This is the method results will be collected with, so they&#39;re comparable.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Setup</th></tr></thead><tbody><tr><td>Single glass</td><td>1 <code>LiquidGlassView</code>, 120 × 360 dp, over a scrolling list</td></tr><tr><td>Several glass</td><td>5 glass views over a scrolling list</td></tr><tr><td>Heavy</td><td>10 glass views</td></tr><tr><td>Stress</td><td>20 glass views (the example app&#39;s Stress screen)</td></tr><tr><td>Moving glass</td><td>6 glass cards scrolling over a still image</td></tr><tr><td>Animated look</td><td><code>material</code> toggled every 500 ms (<code>transitionDuration</code> 300)</td></tr><tr><td>Maximum blur</td><td>1 glass view at <code>blur={100}</code></td></tr><tr><td>Full effect</td><td><code>refraction</code> 1, <code>distortion</code> 0.3, <code>chromaticAberration</code> 0.3, <code>quality=&quot;high&quot;</code></td></tr></tbody></table><p>For each: average FPS, frame time (p50 and p95), dropped frames, CPU and memory, GPU time where measurable, with the device model, OS version and library version.</p><table tabindex="0"><thead><tr><th>Device</th><th>OS</th><th>Library</th><th>Results</th></tr></thead><tbody><tr><td>—</td><td>—</td><td>—</td><td>Pending</td></tr></tbody></table><p>Measured something? Please <a href="https://github.com/SachinMeenaSipl/react-native-glass-effect/issues" target="_blank" rel="noreferrer">share it in an issue</a> with your device and the scenario.</p>',28)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
